package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.New(0, 0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string = ""

var SchedFileLines []string
var SchedFileIndex int = 0
var SchedRecVar SchedRec

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func pow10(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func formatPIC9(n int64, digits int) string {
	if digits <= 0 {
		return ""
	}
	mod := pow10(digits)
	v := n % mod
	if v < 0 {
		v += mod
	}
	fmtStr := fmt.Sprintf("%%0%dd", digits)
	return fmt.Sprintf(fmtStr, v)
}

func formatBalEd(val decimal.Decimal) string {
	// PIC ZZ,ZZZ,ZZ9.99  len 13
	// integer slots 8, decimals 2
	// handle negative?
	neg := val.IsNegative()
	if neg {
		val = val.Neg()
	}
	// ensure scale 2 (already)
	// Truncate high-order digits if more than 8 integer digits
	// total cent modulus 10^(8+2)=10^10
	// Apply modulus to keep low-order digits per spec:
	// If value has more integer digits than picture, high-order dropped
	cents := val.Mul(decimal.New(100, 0)).Truncate(0)
	// cents should be integer; apply mod 10^10
	modCents := decimal.New(pow10(10), 0) // 10^10 = 10000000000 fits in int64 (10B)
	// Use IntPart for mod
	c := cents.IntPart()
	// c may exceed int64? max 9(8)V99 => 9,999,999,999 cents < 10^10 fits
	c = c % 10000000000
	if c < 0 {
		c += 10000000000
	}
	// rebuild val from c
	val = decimal.New(c, -2)

	// integer part and fractional
	intPart := int64(val.IntPart()) // 0 .. 99999999
	frac := (c % 100) // 0..99
	// integer digits string 8 chars zero padded
	intStr := fmt.Sprintf("%08d", intPart)

	// digit slots mapping: picture positions:
	// 0:Z 1:Z 2:',' 3:Z 4:Z 5:Z 6:',' 7:Z 8:Z 9:'9' 10:'.' 11:'9' 12:'9'
	pic := []rune("ZZ,ZZZ,ZZ9.99")
	// digit slot indices in pic:
	// 0,1,3,4,5,7,8,9  -> 8 slots
	slotPos := []int{0, 1, 3, 4, 5, 7, 8, 9}
	// determine first non-zero index in intStr
	firstNonZero := -1
	for i, ch := range intStr {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	// Build output rune slice
	out := make([]rune, len(pic))
	for i, p := range pic {
		switch p {
		case 'Z', '9':
			// will fill later
			_ = i
		case ',', '.':
			out[i] = p
		}
	}
	// fill digit slots
	for si, picIdx := range slotPos {
		digitChar := rune(intStr[si])
		pChar := pic[picIdx]
		if pChar == '9' {
			out[picIdx] = digitChar
		} else { // Z
			if firstNonZero == -1 {
				// value zero => all Z become space
				out[picIdx] = ' '
			} else {
				if si < firstNonZero {
					out[picIdx] = ' '
				} else {
					out[picIdx] = digitChar
				}
			}
		}
	}
	// handle commas: if all digit slots to left are suppressed (space), comma => space
	// For each comma position, check if any significant digit to left exists
	// Significant means slot < firstNonZero is suppressed; otherwise significant
	// If firstNonZero == -1 => no significant digit => all commas space
	// else comma at pic index 2 is after slots 0,1 ; comma at 6 after slots 0..4
	// So determine for each comma, the max slot index to left
	commaPicIdx := []int{2, 6}
	// map comma to last slot idx left of it
	// comma 2: left slots are si 0,1 (picIdx 0,1)
	// comma 6: left slots are si 0,1,2,3,4 (picIdx 0,1,3,4,5)
	leftCount := []int{2, 5} // number of slots to left
	for ci, cIdx := range commaPicIdx {
		if firstNonZero == -1 {
			out[cIdx] = ' '
		} else {
			// if every left slot is suppressed (si < firstNonZero for all left slots)
			// i.e., firstNonZero >= leftCount[ci]
			if firstNonZero >= leftCount[ci] {
				out[cIdx] = ' '
			} else {
				out[cIdx] = ','
			}
		}
	}
	// dot
	out[10] = '.'
	// fractional digits
	out[11] = rune('0' + (frac/10)%10)
	out[12] = rune('0' + frac%10)

	return string(out)
}

func storeWsBal(v decimal.Decimal) decimal.Decimal {
	// PIC 9(8)V99 : scale 2, high-order truncation mod 10^10 cents
	// v is already rounded to 2
	cents := v.Mul(decimal.New(100, 0)).Truncate(0)
	// Apply mod for positive
	mod := int64(10000000000)
	c := cents.IntPart()
	c = c % mod
	if c < 0 {
		c += mod
	}
	return decimal.New(c, -2)
}

func parsePIC9V99(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.New(0, 0)
	}
	// s contains digits only, maybe with spaces; keep digits and sign
	// For unsigned, just digits
	// Remove non-digit
	filtered := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			filtered += string(ch)
		}
	}
	if filtered == "" {
		return decimal.New(0, 0)
	}
	// Parse as integer
	d, err := decimal.NewFromString(filtered)
	if err != nil {
		var v int64 = 0
		for _, ch := range filtered {
			v = v*10 + int64(ch-'0')
		}
		d = decimal.New(v, 0)
	}
	d = d.Shift(-scale)
	return d
}

func parsePIC9(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	filtered := ""
	for _, ch := range s {
		if (ch >= '0' && ch <= '9') || ch == '-' {
			filtered += string(ch)
		}
	}
	if filtered == "" {
		return 0
	}
	var v int64 = 0
	sign := int64(1)
	for i, ch := range filtered {
		if ch == '-' && i == 0 {
			sign = -1
			continue
		}
		if ch >= '0' && ch <= '9' {
			v = v*10 + int64(ch-'0')
		}
	}
	return sign * v
}

func READ_PARA() {
	if SchedFileIndex >= len(SchedFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := SchedFileLines[SchedFileIndex]
	SchedFileIndex++
	// pad/truncate to 16
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	} else if len(line) > 16 {
		line = line[:16]
	}
	// parse fields
	SchedRecVar.ScAcct = line[0:4]
	SchedRecVar.ScPrin = parsePIC9V99(line[4:11], 2)
	SchedRecVar.ScRate = parsePIC9V99(line[11:15], 2)
	SchedRecVar.ScYears = parsePIC9(line[15:16])
}

func PROCESS_PARA() {
	// MOVE SC-PRIN TO WS-BAL
	WsBal = SchedRecVar.ScPrin
	// ensure storage truncation (though fits)
	WsBal = storeWsBal(WsBal)

	WsYear = 1
	for !(WsYear > SchedRecVar.ScYears) {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE /100)
		rateDiv := SchedRecVar.ScRate.Shift(-2) // /100
		onePlus := decimal.New(1, 0).Add(rateDiv)
		res := WsBal.Mul(onePlus)
		res = res.Round(2) // ROUNDED
		WsBal = storeWsBal(res)

		WsBalEd = formatBalEd(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		yearStr := formatPIC9(WsYear, 2)
		// SC-ACCT is X(4) exactly 4 chars
		fmt.Printf("%s Y%s %s\n", SchedRecVar.ScAcct, yearStr, WsBalEd)

		WsYear++
	}
	WsBalEd = formatBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", SchedRecVar.ScAcct, WsBalEd)
	WsCount++
	// ADD 1 TO WS-COUNT with overflow handling (PIC 99)
	WsCount = WsCount % 100
	READ_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT SCHED-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// treat as empty file
		SchedFileLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		lines := []string{}
		for scanner.Scan() {
			txt := scanner.Text()
			// LINE SEQUENTIAL strips newline, keep as is (without newline)
			lines = append(lines, txt)
		}
		f.Close()
		SchedFileLines = lines
	}
	SchedFileIndex = 0
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	// CLOSE handled
	countStr := formatPIC9(WsCount, 2)
	fmt.Printf("SCHEDULES: %s\n", countStr)
}

func main() {
	MAIN_PARA()
}

